                      <Menu.Content class="session-options-menu w-max" style={{ "min-width": "0" }} onCloseAutoFocus={(event) => {
                    if (!title.pendingRename)
                        return;
                    event.preventDefault();
                    setTitle("pendingRename", false);
                    openTitleEditor();
                }}>
                        <Menu.Item onSelect={() => {
                    setTitle("pendingRename", true);
