                      </Menu.Content>
                    </Menu.Portal>
                  </Menu>)}
              </Show>
              <Show when={!title.editing}>
                <SessionHeaderGap active={props.active !== false} register={props.registerHeaderGap}/>
              </Show>
            </SessionHeaderLayout>
