    const builtin = (id) => builtins.some((definition) => definition.id === id);
    // A server plugin's id can be a built-in's (a reserved id), so each row looks up its own kind of item.
    const itemOf = (id, kind) => installed.list().find((item) => item.id === id && item.builtin === (kind === "builtin"));
    const defined = (id) => !builtin(id) && host.definitions().some((definition) => definition.id === id);
