          {(id) => (<div class="settings-servers-actions">
              <Button size="small" variant="ghost" onClick={() => reload(id())}>
                {language.t("settings.plugins.reload")}
              </Button>
              {/* A built-in always runs; it keeps the switch's width, so every Reload lines up. */}
